/** English text for `text` when one exists, otherwise `text` unchanged. */
export function en(text: string): string;
export function en(text: string | undefined): string | undefined;
export function en(text: string | undefined) {
  return text === undefined ? text : (enMap[text] ?? text);
}

/** Locale-aware wrapper: translate only on English pages. */
export function tr(text: string, locale: Locale): string;
export function tr(text: string | undefined, locale: Locale): string | undefined;
export function tr(text: string | undefined, locale: Locale) {
  return locale === 'en' ? en(text) : text;
}
